<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Webhook Inspector</title><style>body{font:15px system-ui;margin:0;background:#fafafa;color:#111}.wrap{max-width:1050px;margin:auto;padding:32px}.panel{background:#fff;border:1px solid #ddd;border-radius:10px;padding:20px;margin:18px 0}.top{display:flex;justify-content:space-between;align-items:center}button,input{padding:9px;border:1px solid #bbb;border-radius:7px}code,pre{font-family:ui-monospace,monospace}pre{background:#111;color:#eee;padding:14px;overflow:auto}</style></head><body><div class="wrap"><div class="top"><div><h1>Webhook Inspector</h1><p>Inspect, debug and replay HTTP webhooks.</p></div>@auth<form method="post" action="/logout">@csrf<button>Sign out</button></form>@else<a href="/login">Sign in</a>@endauth</div>@auth<div class="panel"><h2>Endpoints</h2><input id="name" placeholder="Endpoint name"><button onclick="createEndpoint()">Create</button><div id="list">Loading…</div></div><div class="panel"><h2>Captured requests</h2><div id="requests">Select an endpoint to inspect requests.</div></div>@else<div class="panel"><p>Sign in to manage endpoints.</p></div>@endauth</div>@auth<script>async function api(u,o={}){o.headers={...(o.headers||{}),Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':'{{csrf_token()}}'};return fetch(u,o)}async function load(){let r=await api('/api/endpoints');let j=await r.json();document.querySelector('#list').innerHTML=j.data.map(e=>'<div class="panel"><b>'+e.name+'</b><p><code>'+location.origin+'/webhook/'+e.token+'</code></p><button onclick="requests('+e.id+')">Requests</button><button onclick="removeEndpoint('+e.id+')">Delete</button></div>').join('')}async function createEndpoint(){let n=document.querySelector('#name').value;if(!n)return;await api('/api/endpoints',{method:'POST',body:JSON.stringify({name:n})});document.querySelector('#name').value='';load()}async function removeEndpoint(id){if(confirm('Delete endpoint?')){await api('/api/endpoints/'+id,{method:'DELETE'});load()}}async function requests(id){let r=await api('/api/endpoints/'+id+'/requests');let j=await r.json();document.querySelector('#requests').innerHTML=j.data.map(x=>'<div class="panel"><b>'+x.method+'</b> '+x.received_at+' · '+x.request_size+' bytes<pre>'+JSON.stringify(x.json_body??x.raw_body,null,2)+'</pre></div>').join('')||'No requests.'}load();</script>@endauth</body></html>